// Lab 12.1, provided (you do not edit this file): the Metal host side of copy_keys,
// one thread per key, BLOCK_DIM threads per threadgroup (fewer if the pipeline cannot).
#import <Metal/Metal.h>
#include <algorithm>
#include <cstdint>

#ifndef BLOCK_DIM
#define BLOCK_DIM 256
#endif

void encodeCopyKeys(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                    id<MTLBuffer> input, id<MTLBuffer> output, uint32_t n) {
    if (n == 0) return;
    NSUInteger threads = std::min<NSUInteger>(BLOCK_DIM, pipeline.maxTotalThreadsPerThreadgroup);
    [enc setComputePipelineState:pipeline];
    [enc setBuffer:input offset:0 atIndex:0];
    [enc setBuffer:output offset:0 atIndex:1];
    [enc setBytes:&n length:sizeof(n) atIndex:2];
    [enc dispatchThreadgroups:MTLSizeMake((n + threads - 1) / threads, 1, 1)
        threadsPerThreadgroup:MTLSizeMake(threads, 1, 1)];
}
